insert into public.categories (id, name, description, sort_order) values
  ('phones', 'Phones', 'Smartphones for every budget, brand-new and sealed', 0),
  ('gadgets', 'Gadgets', 'Audio, smartwatches, tablets and speakers', 1),
  ('accessories', 'Accessories', 'Power banks, chargers, cables and cases', 2)
insert into public.product_types (id, name, category_id, sort_order) values
  ('phones', 'Phones', 'phones', 0),
  ('tablets', 'Tablets', 'gadgets', 1),
  ('audio', 'Headsets & earbuds', 'gadgets', 2),
  ('smartwatches', 'Smartwatches', 'gadgets', 3),
  ('speakers', 'Speakers', 'gadgets', 4),
  ('power-banks', 'Power banks', 'accessories', 5),
  ('chargers', 'Chargers & cables', 'accessories', 6),
  ('protection', 'Cases & protection', 'accessories', 7)
insert into public.brands (id, name, tagline, sort_order) values
  ('apple', 'Apple', 'iPhone, AirPods, Apple Watch and official chargers', 0),
  ('samsung', 'Samsung', 'Galaxy phones, tablets, Buds and watches', 1),
  ('google', 'Google', 'Pixel phones, Buds and Pixel Watch', 2),
  ('tecno', 'Tecno', 'Camon, Spark and Pova phones plus accessories', 3),
  ('infinix', 'Infinix', 'Note and Hot series phones and audio', 4),
  ('oraimo', 'Oraimo', 'Earbuds, power banks, chargers and cables', 5),
  ('nova', 'Nova', 'Our own range of phones, audio and accessories', 6)
insert into public.products (id, slug, name, short_description, description, price, discount_percent, image, category_id, brand_id, type_id, stock_quantity, rating, rating_count, featured, specs, sort_order) values
  ('p-001', 'iphone-16-pro-max', 'iPhone 16 Pro Max (256GB)', '6.9" Super Retina XDR, titanium design, 48MP Pro camera.', 'Apple’s biggest and most capable iPhone. A 6.9-inch always-on display, a light titanium body, a 48MP main camera with 5× zoom, and battery life that easily lasts the day. Brand-new and sealed.', 2150000, null, 'images/products/iphone-16-pro-max.svg', 'phones', 'apple', 'phones', 3, 4.9, 214, true, '[{"label":"Display","value":"6.9\" Super Retina XDR, 120Hz"},{"label":"Storage","value":"256GB"},{"label":"Camera","value":"48MP + 48MP ultra-wide + 12MP 5× telephoto"},{"label":"Connector","value":"USB-C"},{"label":"Warranty","value":"12 months"}]'::jsonb, 0),
  ('p-002', 'iphone-15', 'iPhone 15 (128GB)', '6.1" display, Dynamic Island, 48MP camera, USB-C.', 'A brilliant everyday iPhone with Dynamic Island, a sharp 48MP camera and fast USB-C charging, in a tough colour-infused glass design.', 1150000, 5, 'images/products/iphone-15.svg', 'phones', 'apple', 'phones', 8, 4.8, 341, false, '[{"label":"Display","value":"6.1\" Super Retina XDR"},{"label":"Storage","value":"128GB"},{"label":"Camera","value":"48MP + 12MP ultra-wide"},{"label":"Connector","value":"USB-C"},{"label":"Warranty","value":"12 months"}]'::jsonb, 1),
  ('p-003', 'airpods-pro-2', 'AirPods Pro (2nd generation)', 'Active Noise Cancellation, Adaptive Audio, USB-C case.', 'Rich sound with up to twice the noise cancellation of the original AirPods Pro. Transparency mode lets the world in when you need it, and the USB-C case adds up to 30 hours of listening.', 385000, null, 'images/products/airpods-pro-2.svg', 'gadgets', 'apple', 'audio', 14, 4.8, 502, false, '[{"label":"Noise cancelling","value":"Active, adaptive"},{"label":"Battery","value":"Up to 6 hours (30 with case)"},{"label":"Case","value":"USB-C, MagSafe"},{"label":"Warranty","value":"12 months"}]'::jsonb, 2),
  ('p-004', 'apple-watch-series-10', 'Apple Watch Series 10 (42mm)', 'Thinnest Apple Watch yet, with a bigger, brighter display.', 'Track workouts, sleep and heart health, reply to messages and pay from your wrist. Series 10 has Apple’s largest and brightest display in a thinner, lighter case.', 720000, null, 'images/products/apple-watch-series-10.svg', 'gadgets', 'apple', 'smartwatches', 0, 4.7, 96, false, '[{"label":"Case size","value":"42mm aluminium"},{"label":"Battery","value":"Up to 18 hours"},{"label":"Water resistance","value":"50m"},{"label":"Warranty","value":"12 months"}]'::jsonb, 3),
  ('p-005', 'apple-20w-usb-c-adapter', 'Apple 20W USB-C Power Adapter', 'Official fast charger for iPhone and iPad.', 'Charge your iPhone up to 50% in around 30 minutes. The official Apple adapter, made to work safely with every iPhone and iPad that charges over USB-C.', 38000, null, 'images/products/apple-20w-usb-c-adapter.svg', 'accessories', 'apple', 'chargers', 40, 4.7, 688, false, '[{"label":"Output","value":"20 W USB-C"},{"label":"Plug","value":"UK 3-pin"},{"label":"Warranty","value":"12 months"}]'::jsonb, 4),
  ('p-006', 'galaxy-s25-ultra', 'Galaxy S25 Ultra (256GB)', '6.9" Dynamic AMOLED, 200MP camera, built-in S Pen.', 'Samsung’s most powerful Galaxy. A huge 6.9-inch display, a 200MP camera that shines at night, the built-in S Pen for notes and sketches, and Galaxy AI features built in.', 1950000, null, 'images/products/galaxy-s25-ultra.svg', 'phones', 'samsung', 'phones', 6, 4.8, 188, true, '[{"label":"Display","value":"6.9\" Dynamic AMOLED 2X, 120Hz"},{"label":"Storage / RAM","value":"256GB / 12GB"},{"label":"Camera","value":"200MP + 50MP + 50MP + 10MP"},{"label":"Extras","value":"Built-in S Pen"},{"label":"Warranty","value":"12 months"}]'::jsonb, 5),
  ('p-007', 'galaxy-a55', 'Galaxy A55 5G (128GB)', '6.6" Super AMOLED, 50MP OIS camera, metal frame.', 'Premium looks at a mid-range price. A bright 6.6-inch Super AMOLED screen, a steady 50MP camera, a strong metal frame and four years of Android updates.', 520000, 8, 'images/products/galaxy-a55.svg', 'phones', 'samsung', 'phones', 20, 4.6, 274, false, '[{"label":"Display","value":"6.6\" Super AMOLED, 120Hz"},{"label":"Storage / RAM","value":"128GB / 8GB"},{"label":"Battery","value":"5,000mAh, 25W charging"},{"label":"Warranty","value":"12 months"}]'::jsonb, 6),
  ('p-008', 'galaxy-tab-s9-fe', 'Galaxy Tab S9 FE (128GB)', '10.9" tablet with S Pen included. Water-resistant.', 'A big, bright tablet for school, work and movies, with the S Pen in the box and IP68 water resistance.', 640000, null, 'images/products/galaxy-tab-s9-fe.svg', 'gadgets', 'samsung', 'tablets', 7, 4.6, 83, false, '[{"label":"Display","value":"10.9\" TFT, 90Hz"},{"label":"Storage / RAM","value":"128GB / 6GB"},{"label":"In the box","value":"S Pen"},{"label":"Warranty","value":"12 months"}]'::jsonb, 7),
  ('p-009', 'galaxy-buds3-pro', 'Galaxy Buds3 Pro', 'Hi-fi sound, adaptive noise cancelling, blade lights.', 'Studio-quality sound with two-way speakers, intelligent noise cancelling that adapts to your surroundings, and live translation with Galaxy AI.', 310000, null, 'images/products/galaxy-buds3-pro.svg', 'gadgets', 'samsung', 'audio', 12, 4.5, 129, false, '[{"label":"Noise cancelling","value":"Adaptive ANC"},{"label":"Battery","value":"Up to 6 hours (26 with case)"},{"label":"Water resistance","value":"IP57"},{"label":"Warranty","value":"12 months"}]'::jsonb, 8),
  ('p-010', 'galaxy-watch7', 'Galaxy Watch7 (44mm)', 'Health tracking, sleep coaching and GPS.', 'Get personalised health insights, sleep coaching and accurate GPS for your runs, with a bright sapphire-glass display.', 420000, null, 'images/products/galaxy-watch7.svg', 'gadgets', 'samsung', 'smartwatches', 9, 4.5, 77, false, '[{"label":"Case size","value":"44mm"},{"label":"Battery","value":"Up to 40 hours"},{"label":"Works with","value":"Android"},{"label":"Warranty","value":"12 months"}]'::jsonb, 9),
  ('p-011', 'samsung-25w-charger', 'Samsung 25W Super Fast Charger', 'Official USB-C fast charger with cable.', 'Charge your Galaxy at full speed with the official 25W Super Fast Charger. Includes a 1m USB-C to USB-C cable.', 25000, null, 'images/products/samsung-25w-charger.svg', 'accessories', 'samsung', 'chargers', 60, 4.7, 455, false, '[{"label":"Output","value":"25 W USB-C PD"},{"label":"In the box","value":"Charger + 1m cable"},{"label":"Warranty","value":"12 months"}]'::jsonb, 10),
  ('p-012', 'samsung-10000mah-power-bank', 'Samsung 10,000mAh Power Bank (25W)', 'Slim power bank with 25W Super Fast Charging.', 'Slip it in your bag and charge your phone up to twice. Two USB-C ports let you charge two devices at the same time.', 42000, null, 'images/products/samsung-10000mah-power-bank.svg', 'accessories', 'samsung', 'power-banks', 18, 4.6, 160, false, '[{"label":"Capacity","value":"10,000 mAh"},{"label":"Max output","value":"25 W"},{"label":"Ports","value":"2 × USB-C"},{"label":"Warranty","value":"12 months"}]'::jsonb, 11),
  ('p-013', 'pixel-9-pro', 'Pixel 9 Pro (128GB)', '6.3" Super Actua display, pro triple camera, Gemini built in.', 'The best of Google in a compact phone. A pro-level triple camera, a super-bright display and helpful AI built right in, with seven years of updates.', 1650000, null, 'images/products/pixel-9-pro.svg', 'phones', 'google', 'phones', 5, 4.7, 92, false, '[{"label":"Display","value":"6.3\" OLED, 120Hz"},{"label":"Storage / RAM","value":"128GB / 16GB"},{"label":"Camera","value":"50MP + 48MP + 48MP 5× telephoto"},{"label":"Warranty","value":"12 months"}]'::jsonb, 12),
  ('p-014', 'pixel-9a', 'Pixel 9a (128GB)', 'Pixel camera and AI at a friendlier price.', 'Great photos in any light, a smooth 6.3-inch display and Google’s helpful AI features, with all-day battery life and seven years of updates.', 780000, 6, 'images/products/pixel-9a.svg', 'phones', 'google', 'phones', 11, 4.6, 58, false, '[{"label":"Display","value":"6.3\" OLED, 120Hz"},{"label":"Storage / RAM","value":"128GB / 8GB"},{"label":"Battery","value":"5,100mAh"},{"label":"Warranty","value":"12 months"}]'::jsonb, 13),
  ('p-015', 'pixel-buds-pro-2', 'Pixel Buds Pro 2', 'Small, comfortable earbuds with powerful noise cancelling.', 'Google’s lightest Pro earbuds, with Active Noise Cancellation, clear calls and hands-free help from Gemini.', 290000, null, 'images/products/pixel-buds-pro-2.svg', 'gadgets', 'google', 'audio', 4, 4.5, 44, false, '[{"label":"Noise cancelling","value":"Active"},{"label":"Battery","value":"Up to 8 hours (30 with case)"},{"label":"Warranty","value":"12 months"}]'::jsonb, 14),
  ('p-016', 'pixel-watch-3', 'Pixel Watch 3 (41mm)', 'Fitbit health tracking in a sleek round design.', 'Daily readiness, sleep and heart-rate tracking from Fitbit, with Google Maps, Wallet and Assistant on your wrist.', 560000, null, 'images/products/pixel-watch-3.svg', 'gadgets', 'google', 'smartwatches', 6, 4.4, 31, false, '[{"label":"Case size","value":"41mm"},{"label":"Battery","value":"Up to 24 hours"},{"label":"Works with","value":"Android"},{"label":"Warranty","value":"12 months"}]'::jsonb, 15),
  ('p-017', 'tecno-camon-30-pro', 'Tecno Camon 30 Pro 5G (512GB)', '50MP selfie camera, 512GB storage, 70W charging.', 'Made for photos. A 50MP main camera with stabilisation, a sharp 50MP selfie camera, a curved AMOLED display and super-fast 70W charging.', 520000, null, 'images/products/tecno-camon-30-pro.svg', 'phones', 'tecno', 'phones', 15, 4.5, 233, false, '[{"label":"Display","value":"6.78\" AMOLED, 144Hz"},{"label":"Storage / RAM","value":"512GB / 12GB"},{"label":"Battery","value":"5,000mAh, 70W"},{"label":"Warranty","value":"12 months"}]'::jsonb, 16),
  ('p-018', 'tecno-spark-30-pro', 'Tecno Spark 30 Pro (256GB)', '6.78" AMOLED, 108MP camera, 256GB storage.', 'Big features for less. A smooth AMOLED screen, a 108MP main camera, stereo speakers and plenty of storage for apps, photos and videos.', 265000, 10, 'images/products/tecno-spark-30-pro.svg', 'phones', 'tecno', 'phones', 35, 4.4, 410, true, '[{"label":"Display","value":"6.78\" AMOLED, 120Hz"},{"label":"Storage / RAM","value":"256GB / 8GB"},{"label":"Battery","value":"5,000mAh, 33W"},{"label":"Warranty","value":"12 months"}]'::jsonb, 17),
  ('p-019', 'tecno-pova-6-pro', 'Tecno Pova 6 Pro 5G (256GB)', 'Huge 6,000mAh battery and gaming-ready performance.', 'Built for long days and long gaming sessions, with a 6,000mAh battery, 70W fast charging and a 120Hz AMOLED display.', 410000, null, 'images/products/tecno-pova-6-pro.svg', 'phones', 'tecno', 'phones', 10, 4.5, 172, false, '[{"label":"Display","value":"6.78\" AMOLED, 120Hz"},{"label":"Storage / RAM","value":"256GB / 12GB"},{"label":"Battery","value":"6,000mAh, 70W"},{"label":"Warranty","value":"12 months"}]'::jsonb, 18),
  ('p-020', 'tecno-true-wireless-earbuds', 'Tecno True Wireless Earbuds', 'Light everyday earbuds with clear calls.', 'Comfortable everyday earbuds with punchy sound, clear call microphones and a pocket-size charging case.', 24000, null, 'images/products/tecno-true-wireless-earbuds.svg', 'gadgets', 'tecno', 'audio', 30, 4.2, 140, false, '[{"label":"Battery","value":"Up to 5 hours (20 with case)"},{"label":"Water resistance","value":"IPX4"},{"label":"Warranty","value":"6 months"}]'::jsonb, 19),
  ('p-021', 'infinix-note-40-pro', 'Infinix Note 40 Pro (256GB)', 'Curved AMOLED, 108MP camera, wireless charging.', 'A stylish curved-screen phone with a 108MP camera, 45W wired and 20W wireless charging, and JBL-tuned speakers.', 395000, null, 'images/products/infinix-note-40-pro.svg', 'phones', 'infinix', 'phones', 16, 4.4, 198, false, '[{"label":"Display","value":"6.78\" curved AMOLED, 120Hz"},{"label":"Storage / RAM","value":"256GB / 8GB"},{"label":"Battery","value":"5,000mAh, 45W"},{"label":"Warranty","value":"12 months"}]'::jsonb, 20),
  ('p-022', 'infinix-hot-50', 'Infinix Hot 50 (128GB)', 'Slim, tough everyday phone with a 120Hz screen.', 'One of the slimmest phones at its price, with a smooth 120Hz display, a 50MP camera and a 5,000mAh battery.', 210000, 7, 'images/products/infinix-hot-50.svg', 'phones', 'infinix', 'phones', 28, 4.3, 265, false, '[{"label":"Display","value":"6.7\" IPS, 120Hz"},{"label":"Storage / RAM","value":"128GB / 8GB"},{"label":"Battery","value":"5,000mAh, 18W"},{"label":"Warranty","value":"12 months"}]'::jsonb, 21),
  ('p-023', 'infinix-buds', 'Infinix XBuds Earbuds', 'Noise-reducing earbuds with low-latency game mode.', 'Wireless earbuds with environmental noise reduction for calls and a low-latency mode for gaming and videos.', 28000, null, 'images/products/infinix-buds.svg', 'gadgets', 'infinix', 'audio', 0, 4.1, 62, false, '[{"label":"Battery","value":"Up to 6 hours (24 with case)"},{"label":"Water resistance","value":"IPX5"},{"label":"Warranty","value":"6 months"}]'::jsonb, 22),
  ('p-024', 'oraimo-freepods-4', 'Oraimo FreePods 4', 'Noise-cancelling earbuds with 35.5-hour playtime.', 'Popular for a reason: active noise cancellation, deep bass and up to 35.5 hours of playtime with the charging case.', 32000, 10, 'images/products/oraimo-freepods-4.svg', 'gadgets', 'oraimo', 'audio', 45, 4.5, 820, true, '[{"label":"Noise cancelling","value":"Active"},{"label":"Battery","value":"Up to 35.5 hours with case"},{"label":"Water resistance","value":"IPX5"},{"label":"Warranty","value":"12 months"}]'::jsonb, 23),
  ('p-025', 'oraimo-boompop-headphones', 'Oraimo BoomPop 2 Headphones', 'Over-ear wireless headset with 60-hour battery.', 'Comfortable over-ear headphones with booming bass, a built-in mic for calls and up to 60 hours of battery life.', 28000, null, 'images/products/oraimo-boompop-headphones.svg', 'gadgets', 'oraimo', 'audio', 22, 4.4, 307, false, '[{"label":"Battery","value":"Up to 60 hours"},{"label":"Connectivity","value":"Bluetooth 5.3, AUX"},{"label":"Warranty","value":"12 months"}]'::jsonb, 24),
  ('p-026', 'oraimo-traveler-power-bank', 'Oraimo Traveler 20,000mAh Power Bank', 'Fast-charging power bank, ideal for NEPA days.', 'Keep your phone alive through power cuts. Charges most phones four times, with 22.5W fast charging and three ports.', 26000, null, 'images/products/oraimo-traveler-power-bank.svg', 'accessories', 'oraimo', 'power-banks', 50, 4.6, 1210, false, '[{"label":"Capacity","value":"20,000 mAh"},{"label":"Max output","value":"22.5 W"},{"label":"Ports","value":"1 × USB-C, 2 × USB-A"},{"label":"Warranty","value":"12 months"}]'::jsonb, 25),
  ('p-027', 'oraimo-braided-cable', 'Oraimo Braided USB-C Cable (2m)', 'Tough braided cable with 60W fast charging.', 'A strong nylon-braided cable that survives daily bending and travel, supporting fast charging up to 60W.', 4500, null, 'images/products/oraimo-braided-cable.svg', 'accessories', 'oraimo', 'chargers', 90, 4.5, 642, false, '[{"label":"Length","value":"2 m"},{"label":"Max charging","value":"60 W"},{"label":"Warranty","value":"6 months"}]'::jsonb, 26),
  ('p-028', 'oraimo-watch', 'Oraimo Watch 5', 'AMOLED smartwatch with calls and 100+ sport modes.', 'Answer calls from your wrist, track 100+ sports and monitor heart rate and sleep, with a bright AMOLED display.', 45000, null, 'images/products/oraimo-watch.svg', 'gadgets', 'oraimo', 'smartwatches', 20, 4.2, 188, false, '[{"label":"Display","value":"1.43\" AMOLED"},{"label":"Battery","value":"Up to 10 days"},{"label":"Works with","value":"Android and iPhone"},{"label":"Warranty","value":"12 months"}]'::jsonb, 27),
  ('p-029', 'nova-x5-pro', 'Nova X5 Pro', '6.7" AMOLED, 256GB storage, 50MP triple camera.', 'Our best all-rounder. A bright 6.7-inch 120Hz AMOLED display, a 50MP triple camera that handles low light well, and a 5,000mAh battery that easily lasts a full day.', 485000, 8, 'images/products/nova-x5-pro.svg', 'phones', 'nova', 'phones', 12, 4.8, 276, true, '[{"label":"Display","value":"6.7\" AMOLED, 120Hz"},{"label":"Storage / RAM","value":"256GB / 12GB"},{"label":"Battery","value":"5,000mAh, 67W"},{"label":"Warranty","value":"12 months"}]'::jsonb, 28),
  ('p-030', 'nova-tab-11', 'Nova Tab 11', '11" tablet for study, work and streaming. 128GB.', 'A big, sharp 11-inch screen for online classes, documents, movies and video calls, with quad speakers and an 8,000mAh battery.', 340000, null, 'images/products/nova-tab-11.svg', 'gadgets', 'nova', 'tablets', 9, 4.6, 104, false, '[{"label":"Display","value":"11\" 2K, 90Hz"},{"label":"Storage / RAM","value":"128GB / 8GB"},{"label":"Connectivity","value":"Wi-Fi + 4G SIM"},{"label":"Warranty","value":"12 months"}]'::jsonb, 29),
  ('p-031', 'nova-aura-headphones', 'Nova Aura Wireless Headphones', 'Over-ear, active noise cancelling, 40-hour battery.', 'Immerse yourself in rich, detailed sound. Adaptive noise cancelling blocks out the commute, and soft memory-foam cushions stay comfortable for hours.', 85000, 15, 'images/products/nova-aura-headphones.svg', 'gadgets', 'nova', 'audio', 18, 4.7, 312, false, '[{"label":"Battery","value":"Up to 40 hours"},{"label":"Connectivity","value":"Bluetooth 5.3, 3.5mm cable"},{"label":"Warranty","value":"12 months"}]'::jsonb, 30),
  ('p-032', 'nova-echo-speaker', 'Nova Echo Bluetooth Speaker', 'Portable 360° sound, splash-proof, 18-hour battery.', 'Echo fills the room with clear 360° sound and deep bass. Splash-proof, light enough to carry anywhere, and pairs with a second Echo for stereo.', 45000, null, 'images/products/nova-echo-speaker.svg', 'gadgets', 'nova', 'speakers', 0, 4.4, 96, false, '[{"label":"Battery","value":"Up to 18 hours"},{"label":"Water resistance","value":"IPX5"},{"label":"Warranty","value":"12 months"}]'::jsonb, 31),
  ('p-033', 'nova-65w-gan-charger', 'Nova 65W GaN Fast Charger', 'Charge a phone and laptop at once. Compact and cool-running.', 'One small charger for everything: two USB-C ports and one USB-A port, with up to 65W to fast-charge phones, tablets and laptops.', 24000, 10, 'images/products/nova-65w-gan-charger.svg', 'accessories', 'nova', 'chargers', 50, 4.8, 298, false, '[{"label":"Max output","value":"65 W"},{"label":"Ports","value":"2 × USB-C, 1 × USB-A"},{"label":"Plug","value":"UK 3-pin"},{"label":"Warranty","value":"6 months"}]'::jsonb, 32),
  ('p-034', 'nova-volt-power-bank', 'Nova Volt 20,000mAh Power Bank', 'Fast-charge two devices at once.', 'Charges a phone up to four times, supports 22.5W fast charging, and has USB-C and USB-A ports so you can charge two devices together.', 18500, null, 'images/products/nova-volt-power-bank.svg', 'accessories', 'nova', 'power-banks', 40, 4.6, 421, false, '[{"label":"Capacity","value":"20,000 mAh"},{"label":"Max output","value":"22.5 W"},{"label":"Warranty","value":"6 months"}]'::jsonb, 33),
  ('p-035', 'nova-shockproof-case', 'Nova Shockproof Case for X5 Pro', 'Slim case with air-cushioned corners.', 'Keep your phone safe from drops without adding bulk. Air-cushioned corners absorb impact and raised edges protect the screen and camera.', 8500, null, 'images/products/nova-shockproof-case.svg', 'accessories', 'nova', 'protection', 35, 4.4, 162, false, '[{"label":"Fits","value":"Nova X5 Pro"},{"label":"Drop protection","value":"Up to 2 m"}]'::jsonb, 34)
